#include <algorithm>
#include <iostream>
#include <string>
struct Target { virtual ~Target() = default; virtual std::string Request() const = 0; };
class convierte {
public: std::string SpecificRequest() const { return "aloH"; }
};
class conversor : public Target {
    const convierte& original;
public:
    explicit conversor(const convierte& c) : original(c) {}
    std::string Request() const override {
        auto texto = original.SpecificRequest();
        std::reverse(texto.begin(), texto.end());
        return texto;
    }
};
void ClientCode(const Target& destino) { std::cout << destino.Request() << '\n'; }
int main() { convierte servicio; conversor puente(servicio); ClientCode(puente); }

#include <algorithm>
#include <iostream>
#include <memory>
#include <vector>
#include <functional>
struct dispositivo {
    virtual ~dispositivo() = default;
    virtual void doAlgorithm(std::vector<int>& datos) const = 0;
};
struct Ascendente : dispositivo {
    void doAlgorithm(std::vector<int>& d) const override { std::sort(d.begin(), d.end()); }
};
struct Descendente : dispositivo {
    void doAlgorithm(std::vector<int>& d) const override {
        std::sort(d.begin(), d.end(), std::greater<int>());
    }
};
class Context {
    std::unique_ptr<dispositivo> algoritmo;
public:
    void setdispositivo(std::unique_ptr<dispositivo> a) { algoritmo = std::move(a); }
    void ordenar(std::vector<int>& d) const { if(algoritmo) algoritmo->doAlgorithm(d); }
};
int main() {
    Context contexto; std::vector<int> datos{3,1,2};
    contexto.setdispositivo(std::make_unique<Ascendente>()); contexto.ordenar(datos);
    for(int n : datos) std::cout << n << ' ';
    std::cout << '\n';
    contexto.setdispositivo(std::make_unique<Descendente>()); contexto.ordenar(datos);
    for(int n : datos) std::cout << n << ' ';
    std::cout << '\n';
}

#include <algorithm>
#include <iostream>
#include <vector>
struct Ialarma { virtual ~Ialarma() = default; virtual void Update(int valor) = 0; };
class Subject {
    std::vector<Ialarma*> receptores; // Referencias no propietarias.
public:
    void Attach(Ialarma& a) {
        if(std::find(receptores.begin(), receptores.end(), &a) == receptores.end())
            receptores.push_back(&a);
    }
    void Detach(Ialarma& a) {
        receptores.erase(std::remove(receptores.begin(), receptores.end(), &a), receptores.end());
    }
    void Notify(int valor) { for(auto* a : receptores) a->Update(valor); }
};
struct alarma : Ialarma {
    void Update(int valor) override { std::cout << "Alerta " << valor << '\n'; }
};
int main() {
    alarma aviso; Subject emisor;
    emisor.Attach(aviso); emisor.Notify(7);
    emisor.Detach(aviso); emisor.Notify(9);
    // El receptor vive hasta la baja. Update no modifica las suscripciones.
}
